1	// RULES.md §"One table, two copies": the delivery constants that both tiers must
2	// agree on live in docs/DESIGN.md §10 and are copied into the server's
3	// constants.ts and the client's config.dart — files that cannot share an import
4	// (TypeScript and Dart). This guard compares the copies BY NAME PAIR, so a value
5	// changed on one side and forgotten on the other is a finding rather than a
6	// production bug that only shows up as messages silently not delivered.
7	//
8	// Why not the canon `shared-constants` guard: that one counts occurrences of a
9	// declared literal per file. Here the literals collide as substrings ("150" is
10	// inside "1500"), the paired identifiers differ by language convention
11	// (WHISPER_RADIUS_M / whisperRadiusM), and a value only stays guarded as long as
12	// someone remembers to declare it. Pairing the declarations by name needs no
13	// per-value upkeep and reads the same table docs/DESIGN.md §10 publishes.
14	//
15	// Dependency-free by design (a local pack's checks must load without the shared
16	// mount): it builds plain finding objects instead of importing the engine helper.
17	
18	const SERVER_FILE = 'firebase/functions/src/constants.ts';
19	const CLIENT_FILE = 'app/lib/config.dart';
20	const DESIGN_FILE = 'docs/DESIGN.md';
21	
22	// The cross-tier constants: server name ↔ client name. A server-only constant
23	// (PRESENCE_TTL_MS, SEND_COOLDOWN_MS) or a client-only one (the heartbeat
24	// cadence) has no pair and is deliberately absent — only values BOTH tiers
25	// carry can drift apart.
26	const PAIRS = [
27	  { server: 'WHISPER_RADIUS_M', client: 'whisperRadiusM' },
28	  { server: 'SHOUT_RADIUS_M', client: 'shoutRadiusM' },
29	  { server: 'MAX_TEXT_LEN', client: 'maxTextLen' },
30	  { server: 'REGION', client: 'functionsRegion' },
31	];
32	
33	const rule = {
34	  id: 'shouts-and-whispers/cross-tier-constants',
35	  severity: 'blocking',
36	  description: 'The delivery constants the client and the Cloud Functions both carry hold the same value, and match docs/DESIGN.md §10',
37	  doc: '.claudinite/local/packs/shouts-and-whispers/RULES.md',
38	  why: 'the two tiers cannot share an import, so a radius or limit changed on one side and forgotten on the other compiles, passes every test, and only shows up as messages quietly reaching the wrong people',
39	
40	  run(ctx) {
41	    const out = [];
42	    const say = (file, what, fix) => out.push({
43	      rule: rule.id, severity: rule.severity, file, line: null,
44	      what, why: rule.why, fix, doc: rule.doc,
45	    });
46	
47	    const serverText = ctx.read(SERVER_FILE);
48	    const clientText = ctx.read(CLIENT_FILE);
49	    const designText = ctx.read(DESIGN_FILE);
50	
51	    // Staleness guard, the idiom app/test/import_boundary_test.dart already uses:
52	    // a guard that quietly stops finding its subject is worse than no guard.
53	    if (serverText === null || clientText === null) {
54	      say(
55	        serverText === null ? SERVER_FILE : CLIENT_FILE,
56	        `the cross-tier constants guard cannot read ${serverText === null ? SERVER_FILE : CLIENT_FILE}`,
57	        'restore the file, or point the guard at its new home (the paths live at the top of the pack\'s cross-tier-constants.mjs)',
58	      );
59	      return out;
60	    }
61	
62	    for (const pair of PAIRS) {
63	      const server = serverValue(serverText, pair.server);
64	      const client = clientValue(clientText, pair.client);
65	
66	      if (server === null || client === null) {
67	        say(
68	          server === null ? SERVER_FILE : CLIENT_FILE,
69	          `the guard no longer finds ${server === null ? pair.server : pair.client} in ${server === null ? SERVER_FILE : CLIENT_FILE}`,
70	          'a cross-tier constant was renamed or removed on one side — rename it on both, then update the PAIRS map in the pack check',
71	        );
72	        continue;
73	      }
74	
75	      if (server !== client) {
76	        say(
77	          CLIENT_FILE,
78	          `${pair.client} is ${client} but ${SERVER_FILE}'s ${pair.server} is ${server}`,
79	          `make both copies agree with the docs/DESIGN.md §10 row (the server value is the one delivery actually uses)`,
80	        );
81	        continue;
82	      }
83	
84	      // The doc table is the source both copies transcribe. Only a bare integer
85	      // cell is comparable — the table also carries prose cells ("5 min").
86	      const documented = designValue(designText, pair.server);
87	      if (documented !== null && /^\d+$/.test(documented) && documented !== server) {
88	        say(
89	          DESIGN_FILE,
90	          `§10 documents ${pair.server} as ${documented}, but both tiers carry ${server}`,
91	          'update the §10 row, or the two copies — the table is the single source of truth the copies transcribe',
92	        );
93	      }
94	    }
95	
96	    return out;
97	  },
98	};
99	
100	// `export const NAME = <value>;` — the shape every entry in constants.ts uses.
101	function serverValue(text, name) {
102	  const m = new RegExp(`^export const ${name}\\s*=\\s*([^;]+);`, 'm').exec(text);
103	  return m ? normalize(m[1]) : null;
104	}
105	
106	// `const int name = <value>;` / `const String name = '<value>';` — config.dart's shape.
107	function clientValue(text, name) {
108	  const m = new RegExp(`^const\\s+\\w+\\s+${name}\\s*=\\s*([^;]+);`, 'm').exec(text);
109	  return m ? normalize(m[1]) : null;
110	}
111	
112	// The §10 table row: | `NAME` | value | lives in ... |
113	function designValue(text, name) {
114	  if (text === null) return null;
115	  const m = new RegExp(`^\\|\\s*\`${name}\`\\s*\\|([^|]*)\\|`, 'm').exec(text);
116	  return m ? normalize(m[1]) : null;
117	}
118	
119	// Compare values, not spelling: strip whitespace and one layer of quotes so
120	// 'us-central1' and "us-central1" are the same value.
121	function normalize(raw) {
122	  const v = raw.trim();
123	  const quoted = /^(['"])(.*)\1$/.exec(v);
124	  return quoted ? quoted[2] : v;
125	}
126	
127	export default rule;
