1	// RULES.md §"One table, two copies": adding a cross-tier constant is a
2	// four-part change — the docs/DESIGN.md §10 row, the server copy, the client
3	// copy, and the `PAIRS` map in cross-tier-constants.mjs. This guard covers the
4	// fourth part: "a value absent from PAIRS is a value nothing is guarding."
5	//
6	// cross-tier-constants compares the pairs that are ALREADY listed; nothing
7	// compares the list against the tiers. So the failure it cannot see is the
8	// quiet one: a new constant copied into both constants.ts and config.dart but
9	// never added to PAIRS compiles, passes every suite, and passes the pack's own
10	// checks — while the two copies are free to drift apart forever, which is the
11	// exact bug cross-tier-constants exists to catch.
12	//
13	// The datum reconciled is "this constant is carried by both tiers", written
14	// down twice: once as a declaration in each tier's constants file, once as an
15	// entry in PAIRS. Like the pack's other guards it dictates no value, shape, or
16	// behaviour — its finding reads "make the copies agree", never "restore this
17	// constant".
18	//
19	// Detection pairs by NAMING CONVENTION across the two files, not by grepping
20	// for a list of names: a server `export const SHOUT_RADIUS_M` is cross-tier
21	// exactly when config.dart declares its lowerCamel counterpart `shoutRadiusM`.
22	// That is why the single-tier constants stay quiet by construction rather than
23	// by exemption — PRESENCE_TTL_MS, SEND_COOLDOWN_MS and the client's heartbeat
24	// cadence have no counterpart to find, so they are never candidates. The known
25	// cost is the reverse: a pair deliberately named against the convention
26	// (REGION / functionsRegion) is invisible to the convention and is only seen
27	// because it is already in PAIRS. That is a miss, never a false alarm — a
28	// finding here is always a real both-tier constant nothing is guarding.
29	//
30	// Dependency-free by design (a local pack's checks must load without the shared
31	// mount): it builds plain finding objects instead of importing the engine helper.
32	
33	const SERVER_FILE = 'firebase/functions/src/constants.ts';
34	const CLIENT_FILE = 'app/lib/config.dart';
35	const GUARD_FILE = '.claudinite/local/packs/shouts-and-whispers/cross-tier-constants.mjs';
36	
37	// `export const NAME = <value>;` — the shape every entry in constants.ts uses.
38	const SERVER_DECL = /^export const ([A-Z][A-Z0-9_]*)\s*=/gm;
39	// `const int name = ...;` / `const Duration name = ...;` — config.dart's shape.
40	const CLIENT_DECL = /^const\s+\w+\s+([a-z]\w*)\s*=/gm;
41	// One `{ server: 'NAME', client: 'name' }` entry of the guard's PAIRS map.
42	const PAIR_ENTRY = /server:\s*'([^']+)'\s*,\s*client:\s*'([^']+)'/g;
43	
44	const rule = {
45	  id: 'shouts-and-whispers/cross-tier-constant-coverage',
46	  severity: 'blocking',
47	  description: 'Every constant both tiers declare is listed in the cross-tier-constants guard\'s PAIRS map',
48	  doc: '.claudinite/local/packs/shouts-and-whispers/RULES.md',
49	  why: 'cross-tier-constants only compares the pairs it is given, so a constant copied into both tiers but never added to PAIRS is guarded by nothing — the two copies drift apart with every test still green, which is the very failure that guard exists to catch',
50	
51	  run(ctx) {
52	    const out = [];
53	    const say = (file, what, fix) => out.push({
54	      rule: rule.id, severity: rule.severity, file, line: null,
55	      what, why: rule.why, fix, doc: rule.doc,
56	    });
57	
58	    const serverText = ctx.read(SERVER_FILE);
59	    const clientText = ctx.read(CLIENT_FILE);
60	    const guardText = ctx.read(GUARD_FILE);
61	
62	    // Staleness guard, the idiom the pack's other checks already use: a guard
63	    // that quietly stops finding its subject is worse than no guard.
64	    const missing = [SERVER_FILE, CLIENT_FILE, GUARD_FILE]
65	      .find((f, i) => [serverText, clientText, guardText][i] === null);
66	    if (missing) {
67	      say(missing,
68	        `the cross-tier constant coverage guard cannot read ${missing}`,
69	        'restore the file, or point the guard at its new home (the paths live at the top of the pack\'s cross-tier-constant-coverage.mjs)');
70	      return out;
71	    }
72	
73	    const listed = new Set(names(guardText, PAIR_ENTRY, 1));
74	    if (!listed.size) {
75	      say(GUARD_FILE,
76	        `no PAIRS entries found in ${GUARD_FILE} — the coverage guard has nothing to compare the tiers against`,
77	        'keep the guarded pairs as literal `{ server: \'NAME\', client: \'name\' }` entries in the PAIRS map, or point this guard at its new home');
78	      return out;
79	    }
80	
81	    const declared = names(serverText, SERVER_DECL, 1);
82	    if (!declared.length) {
83	      say(SERVER_FILE,
84	        `no exported constants found in ${SERVER_FILE} — the coverage guard has nothing to check`,
85	        'keep the server constants as top-level `export const NAME = ...` declarations, or point the guard at its new home');
86	      return out;
87	    }
88	
89	    const onClient = new Set(names(clientText, CLIENT_DECL, 1));
90	
91	    for (const name of declared) {
92	      if (listed.has(name)) continue;
93	      // Cross-tier by construction: the client declares the same constant under
94	      // the lowerCamel spelling of the same name. A server-only constant has no
95	      // counterpart here and is never a candidate.
96	      const counterpart = camel(name);
97	      if (!onClient.has(counterpart)) continue;
98	
99	      say(SERVER_FILE,
100	        `${name} is declared in ${SERVER_FILE} and ${counterpart} in ${CLIENT_FILE}, but the pair is absent from the PAIRS map in ${GUARD_FILE}`,
101	        `add { server: '${name}', client: '${counterpart}' } to PAIRS — a cross-tier constant is a four-part change (the docs/DESIGN.md §10 row, both copies, and the PAIRS entry), and until the pair is listed nothing compares the two copies`);
102	    }
103	
104	    return out;
105	  },
106	};
107	
108	// Every capture-group-1 match of `pattern` in `text`, in source order.
109	function names(text, pattern, group) {
110	  const found = [];
111	  pattern.lastIndex = 0;
112	  let m;
113	  while ((m = pattern.exec(text)) !== null) found.push(m[group]);
114	  return found;
115	}
116	
117	// SHOUT_RADIUS_M -> shoutRadiusM: the spelling convention the two tiers use for
118	// one constant (TypeScript SCREAMING_SNAKE, Dart lowerCamel).
119	function camel(screamingSnake) {
120	  return screamingSnake
121	    .toLowerCase()
122	    .split('_')
123	    .map((part, i) => (i === 0 ? part : part.charAt(0).toUpperCase() + part.slice(1)))
124	    .join('');
125	}
126	
127	export default rule;
128

/**
 * Single source of truth for backend constants (DESIGN.md §10).
 * Mirrored on the client in app/lib/config.dart.
 */

/** Whisper delivery radius, metres (DESIGN.md §1.3). */
export const WHISPER_RADIUS_M = 150;

/** Shout delivery radius, metres (DESIGN.md §1.3). */
export const SHOUT_RADIUS_M = 1500;

/**
 * How recently a presence heartbeat must have been reported for a user to
 * count as "known to be near" (DESIGN.md §1.2).
 */
export const PRESENCE_TTL_MS = 5 * 60 * 1000;

/** Maximum message text length after trimming (DESIGN.md §4 step 2). */
export const MAX_TEXT_LEN = 500;

/** Minimum interval between sends per user (DESIGN.md §4 step 3, §8). */
export const SEND_COOLDOWN_MS = 5000;

/** Cloud Functions deployment region. */
export const REGION = 'us-central1';
=== CONFIG ===
/// Client-side constants for Shouts & Whispers.
///
/// These mirror `functions/src/constants.ts` — see docs/DESIGN.md §10 for the
/// single-source-of-truth table. Keep the two files in sync.
library;

/// Whisper delivery radius in metres (the people right around you).
const int whisperRadiusM = 150;

/// Shout delivery radius in metres (the whole neighborhood).
const int shoutRadiusM = 1500;

/// Maximum message text length. The client pre-validates; the server enforces.
const int maxTextLen = 500;

/// Presence heartbeat: minimum movement (metres) that always justifies a
/// presence write, and the position-stream distance filter.
const double moveThresholdM = 25;

/// Presence heartbeat: periodic timer cadence while the app is foregrounded.
const Duration heartbeatInterval = Duration(minutes: 2);

/// Presence heartbeat: minimum gap between two presence writes unless the
/// device moved at least [moveThresholdM] metres.
const Duration minWriteGap = Duration(seconds: 30);

/// Region the callable Cloud Functions are deployed to.
const String functionsRegion = 'us-central1';

// Post-hoc enforcement of a task's declared outcome ceiling (per-project-scheduling
// DESIGN §1, §5.5). The executor runs this in code AFTER the subagent finishes:
// the outcome is a ceiling enforced, not merely requested in prose, so a `none`
// task that opened a PR — or an `open-pr` task that merged one — fails the run
// and converges to needs-human. "No change" is always legal.
//
// Pushes to non-default branches (e.g. the conversation-logs prune) are outside
// the PR taxonomy (DESIGN §1) and are not judged here — the caller passes only
// what the task did to PULL REQUESTS.

import { OUTCOMES } from './task-contract.mjs';

// Verify what a task actually did against its declared ceiling.
//   outcome    — the task's declared ceiling ('none' | 'open-pr' | 'merged-pr')
//   openedPr   — did the run open a pull request?
//   mergedPr   — did the run merge (or arm auto-merge on) a pull request?
// Returns { ok, violation } — violation is null when within the ceiling.
export function verifyOutcome({ outcome, openedPr = false, mergedPr = false }) {
  if (!OUTCOMES.includes(outcome)) {
    return { ok: false, violation: `unknown outcome ceiling "${outcome}"` };
  }
  // Merging implies a PR exists; treat a merge as also having opened one so a
  // caller that only reports mergedPr is still judged correctly.
  const opened = openedPr || mergedPr;

  if (outcome === 'none' && opened) {
    return { ok: false, violation: 'a "none" task must not open or merge a pull request' };
  }
  if (outcome === 'open-pr' && mergedPr) {
    return { ok: false, violation: 'an "open-pr" task must not merge a pull request' };
  }
  return { ok: true, violation: null };
}

